//! Device database entries, generated by `tools/devdb/gen_device.py`.

use serde::Deserialize;

#[derive(Debug, Clone, Deserialize)]
pub struct Field {
    pub name: String,
    pub bit: u8,
    pub width: u8,
}

#[derive(Debug, Clone, Deserialize)]
pub struct Sfr {
    pub name: String,
    pub addr: u16,
    #[serde(rename = "impl")]
    pub impl_mask: u8,
    pub access: String,
    pub por: u8,
    pub fields: Vec<Field>,
}

impl Sfr {
    /// Mask of bits that software can write (access character is not 'r' or '-').
    pub fn write_mask(&self) -> u8 {
        let n = self.access.len();
        let mut m = 0u8;
        for (i, ch) in self.access.chars().enumerate() {
            if ch != 'r' && ch != '-' {
                m |= 1 << (n - 1 - i);
            }
        }
        m
    }
    pub fn field(&self, name: &str) -> Option<&Field> {
        self.fields.iter().find(|f| f.name == name)
    }
}

#[derive(Debug, Clone, Deserialize)]
pub struct Range {
    pub begin: u16,
    pub end: u16,
}

#[derive(Debug, Clone, Deserialize)]
pub struct Flash {
    pub words: u32,
    pub pages: Vec<Range>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct ConfigWord {
    pub name: String,
    pub addr: u32,
    pub default: u16,
    pub fields: Vec<Field>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct Device {
    pub name: String,
    pub hw_stack_depth: u8,
    pub flash: Flash,
    pub config: Vec<ConfigWord>,
    pub gpr: Vec<Range>,
    pub common_ram: Range,
    pub gpr_bytes: u16,
    pub core_register_count: u16,
    /// 32 or 64. Sixty-four-bank devices have a 6-bit BSR and MOVLB operand.
    pub bank_count: u16,
    pub sfrs: Vec<Sfr>,
}

const BUILTIN: &[(&str, &str)] = &[
    ("16f15276", include_str!("../../devices/pic16f15276.json")),
    ("16f1619", include_str!("../../devices/pic16f1619.json")),
    ("16f1829", include_str!("../../devices/pic16f1829.json")),
    ("16f18877", include_str!("../../devices/pic16f18877.json")),
    ("16f1937", include_str!("../../devices/pic16f1937.json")),
];

impl Device {
    pub fn from_json(text: &str) -> Result<Device, String> {
        serde_json::from_str(text).map_err(|e| format!("device database: {e}"))
    }

    /// Look up a built-in device by name (case-insensitive, "pic" prefix optional).
    pub fn builtin(name: &str) -> Result<Device, String> {
        let n = name.to_ascii_lowercase();
        let n = n.strip_prefix("pic").unwrap_or(&n);
        match BUILTIN.iter().find(|(k, _)| *k == n) {
            Some((_, json)) => Device::from_json(json),
            None => Err(format!(
                "unknown device '{name}' (known: {})",
                BUILTIN.iter().map(|(k, _)| format!("pic{k}")).collect::<Vec<_>>().join(", ")
            )),
        }
    }

    pub fn sfr(&self, name: &str) -> Option<&Sfr> {
        self.sfrs.iter().find(|s| s.name == name)
    }

    pub fn sfr_addr(&self, name: &str) -> Option<u16> {
        self.sfr(name).map(|s| s.addr)
    }

    /// Size of the banked data space in bytes.
    pub fn data_size(&self) -> usize {
        self.bank_count as usize * 128
    }

    /// The first SFR, in address order, that has a field with one of these
    /// names, with the field's mask: for flags whose register differs
    /// between families.
    pub fn find_field(&self, sfr_prefix: &str, fields: &[&str]) -> Option<(u16, u8)> {
        for s in self.sfrs.iter().filter(|s| s.name.starts_with(sfr_prefix)) {
            for name in fields {
                if let Some(f) = s.field(name) {
                    return Some((s.addr, (((1u16 << f.width) - 1) as u8) << f.bit));
                }
            }
        }
        None
    }

    /// Mask for a named field of a named SFR, e.g. ("PIR1", "TXIF").
    pub fn field_mask(&self, sfr: &str, field: &str) -> Option<u8> {
        let f = self.sfr(sfr)?.field(field)?;
        Some((((1u16 << f.width) - 1) as u8) << f.bit)
    }

    /// Translate a linear-view offset (FSR address minus 0x2000) to a
    /// traditional data address, or None past the end of GPR memory.
    pub fn linear_to_traditional(&self, mut off: u16) -> Option<u16> {
        for r in &self.gpr {
            let len = r.end - r.begin;
            if off < len {
                return Some(r.begin + off);
            }
            off -= len;
        }
        None
    }
}
